                        try:
                            start, end = addr_range.split('-')
                            start = int(start, 16)
                            end = int(end, 16)

                            # Try to read this region
                            with open(mem_file, 'rb') as mem:
                                mem.seek(start)
                                data = mem.read(min(end - start, 1024*1024))  # Read up to 1MB

